// A trait with a nested type member
template<typename T> struct TypeInfo { using value_type = T; };

// A template specialization where 'type' is a value, not a type
struct SpecialCase {};
template<> struct TypeInfo<SpecialCase> { static int value_type; };

// Function template demonstrating the need for 'typename'
template<typename T>
void process_type() {
  // typename is mandatory here because TypeInfo<T>::value_type is a dependent name
  typename TypeInfo<T>::value_type myVar;
  // Without typename, the compiler would assume value_type is a static member
  // and expect a multiplication, leading to a parse error.
}
